script:
/* The publication pages (pub_*.js). Sizes were measured from the old pages. */

.cafe-p-root {
  color: #0f0f0f;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
}
.cafe-p-root [hidden] {
  display: none !important;
}
.cafe-p-icon {
  display: inline-flex;
  flex-shrink: 0;
}
.cafe-p-icon svg {
  width: 100%;
  height: 100%;
}
.cafe-p-tiny {
  width: 14px;
  height: 14px;
}
.cafe-p-small {
  width: 16px;
  height: 16px;
}
.cafe-p-faint {
  color: #7c7c7c;
}
.cafe-p-skeleton {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.cafe-p-skeleton .cafe-skeleton {
  height: 16px;
  border-radius: 6px;
  background: linear-gradient(90deg, #f3f3f3, #fafafa, #f3f3f3);
  background-size: 200% 100%;
  animation: cafe-pulse 1.2s ease-in-out infinite;
}
.cafe-p-empty {
  margin: 0;
  padding: 40px 0;
  color: #525252;
  text-align: center;
}

/* ---- Avatars and badges ---- */
.cafe-p-avatar {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 9999px;
  background: #f3f3f3;
  color: #7c7c7c;
  font-weight: 500;
  text-transform: uppercase;
}
.cafe-p-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.cafe-p-avatar-sm {
  width: 20px;
  height: 20px;
  font-size: 13px;
}
.cafe-p-avatar-md {
  width: 24px;
  height: 24px;
  font-size: 14px;
}
.cafe-p-badge {
  display: inline-flex;
  height: 16px;
  flex-shrink: 0;
  align-items: center;
  padding: 0 6px;
  border-radius: 6px;
  font-size: 12px;
  letter-spacing: 0.02em;
  line-height: 13.8px;
  white-space: nowrap;
}
.cafe-p-badge.gray {
  background: #f3f3f3;
  color: #525252;
}
.cafe-p-badge.blue {
  background: #e6f1fe;
  color: #0b62c4;
}
.cafe-p-badge.solid-green {
  background: #278f5e;
  color: #fff;
}
.cafe-p-badge.clickable {
  cursor: pointer;
}

/* ---- A publication ---- */
.cafe-p-head {
  display: flex;
  align-items: center;
  gap: 16px;
}
.cafe-p-tile {
  display: flex;
  width: 64px;
  height: 64px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 16px;
  background: #171717;
  color: #fff;
  font-size: 20px;
  font-weight: 600;
  text-transform: uppercase;
}
.cafe-p-head-body {
  min-width: 0;
  flex: 1;
}
.cafe-p-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.cafe-p-title {
  min-width: 0;
  margin: 0;
  color: #0f0f0f;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 20.7px;
}
.cafe-p-share {
  display: grid;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: #f3f3f3;
  color: #171717;
  cursor: pointer;
}
.cafe-p-share:hover {
  background: #ededed;
}
.cafe-p-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  color: #7c7c7c;
  font-size: 13px;
}
.cafe-p-site {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.cafe-p-desc {
  margin: 8px 0 0;
  color: #525252;
  font-size: 13px;
  letter-spacing: 0.015em;
  line-height: 1.5;
}
.cafe-p-members-link {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}
.cafe-p-members-link:hover {
  opacity: 0.8;
}
.cafe-p-stack {
  display: flex;
}
.cafe-p-stack .cafe-p-avatar {
  box-shadow: 0 0 0 2px #c9e2fe;
}
.cafe-p-stack .cafe-p-avatar + .cafe-p-avatar {
  margin-left: -8px;
}
.cafe-p-counts {
  color: #7c7c7c;
  font-size: 13px;
}
.cafe-p-posts {
  margin-top: 24px;
}
.cafe-p-posts > * + * {
  border-top: 1px solid #ededed;
}
.cafe-p-post {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 0;
}
.cafe-p-post-text {
  min-width: 0;
  flex: 1;
}
.cafe-p-post-title {
  color: #0f0f0f;
  font-weight: 500;
  letter-spacing: 0.015em;
  line-height: 16.1px;
}
.cafe-p-post-excerpt {
  display: -webkit-box;
  margin: 4px 0 0;
  overflow: hidden;
  color: #525252;
  font-size: 13px;
  letter-spacing: 0.015em;
  line-height: 1.5;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.cafe-p-post-meta {
  margin-top: 8px;
  color: #7c7c7c;
  font-size: 12px;
}
.cafe-p-post-cover {
  width: 96px;
  height: 80px;
  flex-shrink: 0;
  border-radius: 6px;
  object-fit: cover;
}

/* ---- Members ---- */
.cafe-p-members-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}
.cafe-p-members-left {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
}
.cafe-p-back {
  display: flex;
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  color: #525252;
}
.cafe-p-back:hover {
  background: #f3f3f3;
}
.cafe-p-h1 {
  min-width: 0;
  margin: 0;
  color: #0f0f0f;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.cafe-p-invite {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
}
.cafe-p-section {
  margin-bottom: 24px;
}
.cafe-p-section-title {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
  color: #525252;
  font-size: 13px;
  font-weight: 500;
}
.cafe-p-card {
  border: 1px solid #ededed;
  border-radius: 6px;
}
.cafe-p-card > * + * {
  border-top: 1px solid #ededed;
}
.cafe-p-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
}
.cafe-p-row-text {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 6px;
}
.cafe-p-row-name {
  overflow: hidden;
  color: #0f0f0f;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-p-row-name.grow {
  flex: 1;
  min-width: 0;
}
.cafe-p-cancel {
  height: 24px;
  padding: 0 8px;
}

/* ---- Invite ---- */
.cafe-p-search {
  position: relative;
  margin-top: 8px;
}
.cafe-p-search-icon {
  position: absolute;
  top: 6px;
  left: 8px;
  width: 16px;
  height: 16px;
  color: #7c7c7c;
  pointer-events: none;
}
.cafe-p-search input {
  display: block;
  width: 100%;
  height: 28px;
  padding: 6px 8px 6px 32px;
  border: 1px solid #f3f3f3;
  border-radius: 8px;
  outline: none;
  background: #f3f3f3;
  color: #171717;
  font: inherit;
  font-size: 14px;
}
.cafe-p-search input:hover {
  background: #ededed;
  border-color: #ededed;
}
.cafe-p-search input:focus {
  border-color: #999;
  background: #fff;
  box-shadow: 0 0 1px rgba(0, 0, 0, 0.2), 0 1px 3px rgba(0, 0, 0, 0.14);
}
.cafe-p-search input::placeholder {
  color: #7c7c7c;
  opacity: 1;
}
.cafe-p-results {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 16px;
}
.cafe-p-person {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 12px;
  padding: 8px;
  border: 0;
  border-radius: 4px;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.cafe-p-person:hover {
  background: #f8f8f8;
}
.cafe-p-person-text {
  min-width: 0;
  flex: 1;
  position: relative;
  top: 1px;
  line-height: 24px;
}
.cafe-p-person-name {
  color: #171717;
}
.cafe-p-person-user {
  margin-left: 6px;
  color: #7c7c7c;
  font-size: 13px;
  letter-spacing: 0.02em;
}
.cafe-p-selected {
  padding: 12px;
  border: 1px solid #ededed;
  border-radius: 6px;
}
.cafe-p-selected-top {
  display: flex;
  align-items: center;
  gap: 12px;
}
.cafe-p-selected-name {
  color: #171717;
}
.cafe-p-selected .cafe-p-person-user {
  display: block;
  margin: 0;
}
.cafe-p-x {
  display: grid;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: none;
  color: #7c7c7c;
  cursor: pointer;
}
.cafe-p-x:hover {
  background: #f3f3f3;
  color: #383838;
}
.cafe-p-selected .cafe-field {
  margin-top: 12px;
}
.cafe-p-send {
  width: 100%;
  margin-top: 12px;
}

@media (max-width: 767px) {
  .cafe-container-pub {
    padding: 32px 20px !important;
  }
  .cafe-container-invite {
    padding: 24px 16px !important;
  }
  .cafe-p-h1 {
    font-size: 17px;
    line-height: 19.55px;
  }
}
